import os
import json

# Check the arc task directory
task_dir = '/tmp/arc-pa-tamdyjr_'
if os.path.exists(task_dir):
    # Walk through all files
    for root, dirs, files in os.walk(task_dir):
        level = root.replace(task_dir, '').count(os.sep)
        indent = ' ' * 2 * level
        print(f'{indent}{os.path.basename(root)}/')
        subindent = ' ' * 2 * (level + 1)
        for file in files:
            filepath = os.path.join(root, file)
            if file.endswith('.txt') or file.endswith('.json') or file.endswith('.log'):
                try:
                    with open(filepath, 'r') as f:
                        content = f.read()
                        print(f'{subindent}{file}')
                        print(f'{subindent}  {content[:200]}')
                except:
                    print(f'{subindent}{file} (unreadable)')

# Also check for "result" or "done" subdirectory
for item in os.listdir(task_dir):
    item_path = os.path.join(task_dir, item)
    print(f"Checking {item_path}:")
    if os.path.isdir(item_path):
        print(f"  Directory with contents: {os.listdir(item_path)}")
    else:
        print(f"  File: {json.dumps(item_path)}")

